"""``missionctl`` — a thin HTTP client over the Mission Control API.

Talks to the API over ``httpx`` only; never touches the database or the
``services``/``models`` layers directly (FR-18). Output is JSON,
pretty-printed (§10 #15).

The session (bearer token + basic profile) issued by ``login`` is cached
locally at ``~/.missionctl/session.json`` (override via
``MISSIONCTL_SESSION_FILE``, mainly for tests) so later commands don't need
the token pasted in every time. The file is written best-effort
owner-only (``chmod 600``) since it holds a live bearer token.
"""

from __future__ import annotations

import contextlib
import json
import os
from pathlib import Path
from typing import Any

import httpx
import typer

app = typer.Typer(
    name="missionctl",
    help="A thin HTTP client over the Mission Control API.",
)

DEFAULT_API_BASE_URL = "http://127.0.0.1:8000"


def _api_base_url() -> str:
    return os.environ.get("MISSIONCTL_API_BASE_URL", DEFAULT_API_BASE_URL)


def _session_file() -> Path:
    override = os.environ.get("MISSIONCTL_SESSION_FILE")
    if override:
        return Path(override)
    return Path.home() / ".missionctl" / "session.json"


def _save_session(token: str, user: dict[str, Any]) -> None:
    path = _session_file()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps({"token": token, "user": user}, indent=2))
    # Best-effort only — e.g. unsupported on some Windows filesystems.
    with contextlib.suppress(OSError):
        os.chmod(path, 0o600)


def _load_session() -> dict[str, Any] | None:
    path = _session_file()
    if not path.exists():
        return None
    return json.loads(path.read_text())


def _print_json(payload: Any) -> None:
    typer.echo(json.dumps(payload, indent=2))


def _error_detail(response: httpx.Response) -> Any:
    if not response.content:
        return response.reason_phrase
    try:
        return response.json().get("detail", response.text)
    except ValueError:
        return response.text


@app.command()
def version() -> None:
    """Print the CLI version."""
    typer.echo("missionctl 0.1.0")


@app.command()
def login(email: str, password: str) -> None:
    """Log in and cache the issued bearer token locally."""
    response = httpx.post(
        f"{_api_base_url()}/auth/login",
        json={"email": email, "password": password},
    )
    if response.status_code != httpx.codes.OK:
        _print_json({"error": _error_detail(response)})
        raise typer.Exit(code=1)

    data = response.json()
    _save_session(data["token"], data["user"])
    _print_json({"status": "logged in", "user": data["user"]})


@app.command()
def whoami() -> None:
    """Show the currently logged-in user, verified against the API."""
    session_data = _load_session()
    if session_data is None:
        _print_json({"error": "Not logged in. Run `missionctl login <email> <password>`."})
        raise typer.Exit(code=1)

    response = httpx.get(
        f"{_api_base_url()}/auth/whoami",
        headers={"Authorization": f"Bearer {session_data['token']}"},
    )
    if response.status_code != httpx.codes.OK:
        _print_json({"error": "Session invalid or expired. Run `missionctl login` again."})
        raise typer.Exit(code=1)

    _print_json(response.json())


# --- shared plumbing for every command below this point (T3+) --------------


def _require_session() -> dict[str, Any]:
    session_data = _load_session()
    if session_data is None:
        _print_json({"error": "Not logged in. Run `missionctl login <email> <password>`."})
        raise typer.Exit(code=1)
    return session_data


def _auth_headers(session_data: dict[str, Any]) -> dict[str, str]:
    return {"Authorization": f"Bearer {session_data['token']}"}


def _handle_response(response: httpx.Response) -> Any:
    """Print+exit on any error status; otherwise return the parsed body (or
    ``None`` for a body-less response, e.g. a 204)."""
    if response.status_code >= httpx.codes.BAD_REQUEST:
        _print_json({"error": _error_detail(response)})
        raise typer.Exit(code=1)
    return response.json() if response.content else None


# --- profile (FR-4) ---------------------------------------------------------

profile_app = typer.Typer(help="Crew profile self-service (FR-4).")
app.add_typer(profile_app, name="profile")


@profile_app.command("show")
def profile_show(
    user_id: int | None = typer.Argument(
        None, help="Crew member id to view (defaults to yourself)."
    ),
) -> None:
    """View a crew profile: your own, or (Director/Lead) another crew
    member's in your org, read-only."""
    session_data = _require_session()
    target = user_id if user_id is not None else session_data["user"]["id"]
    response = httpx.get(
        f"{_api_base_url()}/crew/{target}/profile",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@profile_app.command("update")
def profile_update(
    name: str | None = typer.Option(None, help="New display name."),
    contact: str | None = typer.Option(None, help="New contact info."),
    bio: str | None = typer.Option(None, help="New bio."),
) -> None:
    """Update your own name/contact/bio (PATCH-style: only given fields
    change)."""
    session_data = _require_session()
    user_id = session_data["user"]["id"]
    payload = {
        key: value
        for key, value in {"name": name, "contact": contact, "bio": bio}.items()
        if value is not None
    }
    response = httpx.patch(
        f"{_api_base_url()}/crew/{user_id}/profile",
        json=payload,
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


# --- skills: org taxonomy (FR-5) + crew proficiency (FR-6) -----------------

skills_app = typer.Typer(help="Org skill taxonomy and crew skill proficiency (FR-5/FR-6).")
app.add_typer(skills_app, name="skills")


@skills_app.command("add")
def skills_add(
    name: str,
    category: str | None = typer.Option(None, help="Optional free-text category tag."),
) -> None:
    """Create an org-scoped skill (Director only)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/skills",
        json={"name": name, "category": category},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@skills_app.command("list")
def skills_list() -> None:
    """List your org's skill taxonomy."""
    session_data = _require_session()
    response = httpx.get(f"{_api_base_url()}/skills", headers=_auth_headers(session_data))
    _print_json(_handle_response(response))


@skills_app.command("set")
def skills_set(
    skill: str,
    proficiency: int,
    user_id: int | None = typer.Option(
        None, "--user", help="Crew member id to set on behalf of (Director only)."
    ),
) -> None:
    """Set your own (or, as Director, another crew member's) proficiency
    (1-5) on an org skill."""
    session_data = _require_session()
    target = user_id if user_id is not None else session_data["user"]["id"]
    response = httpx.put(
        f"{_api_base_url()}/crew/{target}/skills",
        json={"skill_name": skill, "proficiency": proficiency},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


# --- availability (FR-7) ----------------------------------------------------

availability_app = typer.Typer(help="Crew availability windows (FR-7).")
app.add_typer(availability_app, name="availability")


@availability_app.command("add")
def availability_add(start: str, end: str) -> None:
    """Add an unavailability window (self only), as YYYY-MM-DD dates."""
    session_data = _require_session()
    user_id = session_data["user"]["id"]
    response = httpx.post(
        f"{_api_base_url()}/crew/{user_id}/availability",
        json={"start_date": start, "end_date": end},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@availability_app.command("remove")
def availability_remove(window_id: int) -> None:
    """Delete an unavailability window (delete-only, no edit)."""
    session_data = _require_session()
    user_id = session_data["user"]["id"]
    response = httpx.delete(
        f"{_api_base_url()}/crew/{user_id}/availability/{window_id}",
        headers=_auth_headers(session_data),
    )
    _handle_response(response)
    _print_json({"status": "removed", "id": window_id})


@availability_app.command("list")
def availability_list() -> None:
    """List your own unavailability windows."""
    session_data = _require_session()
    user_id = session_data["user"]["id"]
    response = httpx.get(
        f"{_api_base_url()}/crew/{user_id}/availability",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


# --- missions: lifecycle + approval gate (FR-8/FR-9/FR-10/FR-11/FR-12) -----

mission_app = typer.Typer(
    help="Mission CRUD, requirements, and the 6-state lifecycle (FR-8..FR-12)."
)
app.add_typer(mission_app, name="mission")


@mission_app.command("create")
def mission_create(name: str, description: str, start: str, end: str) -> None:
    """Create a mission (Mission Lead or Director); starts in `draft`, as
    YYYY-MM-DD dates."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions",
        json={"name": name, "description": description, "start_date": start, "end_date": end},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("add-requirement")
def mission_add_requirement(
    mission_id: int, skill_id: int, min_proficiency: int, headcount: int
) -> None:
    """Attach a requirement (skill, minimum proficiency, headcount) to a
    `draft` mission."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/requirements",
        json={"skill_id": skill_id, "min_proficiency": min_proficiency, "headcount": headcount},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("submit")
def mission_submit(mission_id: int) -> None:
    """Submit a `draft` mission for approval (creator only)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/submit",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("approve")
def mission_approve(mission_id: int) -> None:
    """Approve a `pending_approval` mission (Director, not its creator)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/approve",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("reject")
def mission_reject(
    mission_id: int,
    reason: str = typer.Option(..., "--reason", help="Why the mission is being rejected."),
) -> None:
    """Reject a `pending_approval` mission back to `draft` (Director, not
    its creator); requires a reason."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/reject",
        json={"reason": reason},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("activate")
def mission_activate(mission_id: int) -> None:
    """Activate an `approved` mission (Mission Lead or Director)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/activate",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("complete")
def mission_complete(mission_id: int) -> None:
    """Complete an `active` mission (Mission Lead or Director)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/complete",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("cancel")
def mission_cancel(mission_id: int) -> None:
    """Cancel a mission from any pre-completed state (Mission Lead or
    Director)."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/missions/{mission_id}/cancel",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("show")
def mission_show(mission_id: int) -> None:
    """Show a mission's status, requirements, and fulfillment (FR-17)."""
    session_data = _require_session()
    response = httpx.get(
        f"{_api_base_url()}/missions/{mission_id}",
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@mission_app.command("list")
def mission_list() -> None:
    """List missions in your org."""
    session_data = _require_session()
    response = httpx.get(f"{_api_base_url()}/missions", headers=_auth_headers(session_data))
    _print_json(_handle_response(response))


# --- matcher: retrieval + ranking (FR-13) -----------------------------------

match_app = typer.Typer(help="Run the matching engine against a mission (FR-13).")
app.add_typer(match_app, name="match")


@match_app.command("run")
def match_run(
    mission_id: int,
    requirement: int | None = typer.Option(
        None,
        "--requirement",
        help="Match only this requirement id; omit to match every requirement on the mission.",
    ),
) -> None:
    """Run the matcher for a mission: per-requirement ranked candidates with
    score breakdowns (FR-13). Matches every requirement on the mission by
    default; pass `--requirement` to match just one."""
    session_data = _require_session()
    params = {"requirement_id": requirement} if requirement is not None else {}
    response = httpx.get(
        f"{_api_base_url()}/missions/{mission_id}/match",
        params=params,
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


# --- assignments: propose, respond, double-booking guard (FR-14/FR-15/FR-16)


assign_app = typer.Typer(help="Propose and respond to assignments (FR-14/FR-15/FR-16).")
app.add_typer(assign_app, name="assign")


@assign_app.command("propose")
def assign_propose(mission_id: int, requirement_id: int, crew_id: int) -> None:
    """Propose a crew member for a requirement (Mission Lead or Director);
    up to the requirement's headcount."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/assignments",
        json={"mission_id": mission_id, "requirement_id": requirement_id, "crew_id": crew_id},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


@assign_app.command("respond")
def assign_respond(assignment_id: int, action: str) -> None:
    """Accept or decline a proposed assignment (`accept` or `decline`) —
    the assignment's named crew member only."""
    session_data = _require_session()
    response = httpx.post(
        f"{_api_base_url()}/assignments/{assignment_id}/respond",
        json={"action": action},
        headers=_auth_headers(session_data),
    )
    _print_json(_handle_response(response))


assignment_app = typer.Typer(help="List assignments (FR-14/FR-15).")
app.add_typer(assignment_app, name="assignment")


@assignment_app.command("list")
def assignment_list() -> None:
    """List assignments: your own if you're a crew member, your whole org's
    if you're a Mission Lead or Director."""
    session_data = _require_session()
    response = httpx.get(f"{_api_base_url()}/assignments", headers=_auth_headers(session_data))
    _print_json(_handle_response(response))


if __name__ == "__main__":
    app()

"""``/crew/{user_id}/...`` — profile self-service, skill proficiency, and
availability windows (FR-4/FR-6/FR-7).

Every route below is org-scoped through ``services.crew.get_crew_member``
(FR-1: cross-org id -> 404). On top of that, each carries its own identity
rule beyond plain ``require_role`` RBAC:

* profile view  — self, or a Director/Lead viewing another crew member (FR-4)
* profile edit  — self only, and only a crew member (FR-4)
* skill set     — self, or a Director acting on the crew member's behalf (FR-6)
* availability  — self only, always (FR-7 names no "on behalf of" case)
"""

from __future__ import annotations

from datetime import date

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field, model_validator
from sqlmodel import Session

from api.deps import get_current_user
from models.availability_window import AvailabilityWindow
from models.database import get_session
from models.enums import Role
from models.user import User
from services.crew import (
    CrewMemberNotFoundError,
    CrewProfileView,
    OverlappingWindowError,
    SkillNotFoundError,
    WindowNotFoundError,
    add_availability_window,
    list_crew_availability_windows,
    remove_availability_window,
    set_crew_skill_proficiency,
    update_crew_profile,
    view_crew_profile,
)

router = APIRouter(prefix="/crew", tags=["crew"])


# --- schemas ---------------------------------------------------------------


class CrewSkillOut(BaseModel):
    skill_id: int
    skill_name: str
    proficiency: int


class CrewProfileOut(BaseModel):
    user_id: int
    org_id: int
    name: str
    email: str
    contact: str | None
    bio: str | None
    skills: list[CrewSkillOut]


class CrewProfileUpdateRequest(BaseModel):
    name: str | None = None
    contact: str | None = None
    bio: str | None = None


class CrewSkillSetRequest(BaseModel):
    skill_name: str
    proficiency: int = Field(ge=1, le=5)


class AvailabilityWindowCreateRequest(BaseModel):
    start_date: date
    end_date: date

    @model_validator(mode="after")
    def _end_not_before_start(self) -> AvailabilityWindowCreateRequest:
        if self.end_date < self.start_date:
            raise ValueError("end_date must not be before start_date")
        return self


class AvailabilityWindowOut(BaseModel):
    id: int
    crew_id: int
    start_date: date
    end_date: date


# --- helpers -----------------------------------------------------------


def _to_profile_out(view: CrewProfileView) -> CrewProfileOut:
    return CrewProfileOut(
        user_id=view.user.id,  # type: ignore[arg-type]
        org_id=view.user.org_id,
        name=view.user.name,
        email=view.user.email,
        contact=view.profile.contact,
        bio=view.profile.bio,
        skills=[
            CrewSkillOut(skill_id=skill.id, skill_name=skill.name, proficiency=cs.proficiency)  # type: ignore[arg-type]
            for cs, skill in view.skills
        ],
    )


def _to_window_out(window: AvailabilityWindow) -> AvailabilityWindowOut:
    return AvailabilityWindowOut.model_validate(window, from_attributes=True)


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Crew member not found")


def _forbidden(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=detail)


def _require_view_access(caller: User, target_user_id: int) -> None:
    if caller.id == target_user_id:
        return
    if caller.role in (Role.DIRECTOR, Role.MISSION_LEAD):
        return
    raise _forbidden("Requires role: director, mission_lead (or viewing your own profile)")


def _require_self_edit(caller: User, target_user_id: int) -> None:
    if caller.id != target_user_id or caller.role != Role.CREW_MEMBER:
        raise _forbidden("Requires role: crew_member, editing your own profile")


def _require_skill_set_access(caller: User, target_user_id: int) -> None:
    if caller.role == Role.DIRECTOR:
        return
    if caller.role == Role.CREW_MEMBER and caller.id == target_user_id:
        return
    raise _forbidden("Requires role: director, or crew_member setting your own proficiency")


def _require_self_crew(caller: User, target_user_id: int) -> None:
    if caller.id != target_user_id or caller.role != Role.CREW_MEMBER:
        raise _forbidden("Requires role: crew_member, managing your own availability")


# --- profile -----------------------------------------------------------


@router.get("/{user_id}/profile", response_model=CrewProfileOut)
def get_crew_profile_route(
    user_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewProfileOut:
    _require_view_access(caller, user_id)
    try:
        view = view_crew_profile(session, caller.org_id, user_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return _to_profile_out(view)


@router.patch("/{user_id}/profile", response_model=CrewProfileOut)
def update_crew_profile_route(
    user_id: int,
    payload: CrewProfileUpdateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewProfileOut:
    _require_self_edit(caller, user_id)
    try:
        view = update_crew_profile(
            session,
            caller.org_id,
            user_id,
            name=payload.name,
            contact=payload.contact,
            bio=payload.bio,
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return _to_profile_out(view)


# --- skill proficiency ---------------------------------------------------


@router.put("/{user_id}/skills", response_model=CrewSkillOut)
def set_crew_skill_route(
    user_id: int,
    payload: CrewSkillSetRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewSkillOut:
    _require_skill_set_access(caller, user_id)
    try:
        crew_skill, skill = set_crew_skill_proficiency(
            session, caller.org_id, user_id, payload.skill_name, payload.proficiency
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except SkillNotFoundError as exc:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Skill '{payload.skill_name}' not found in this org",
        ) from exc
    return CrewSkillOut(
        skill_id=skill.id,  # type: ignore[arg-type]
        skill_name=skill.name,
        proficiency=crew_skill.proficiency,
    )


# --- availability --------------------------------------------------------


@router.post(
    "/{user_id}/availability",
    response_model=AvailabilityWindowOut,
    status_code=status.HTTP_201_CREATED,
)
def add_availability_window_route(
    user_id: int,
    payload: AvailabilityWindowCreateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> AvailabilityWindowOut:
    _require_self_crew(caller, user_id)
    try:
        window = add_availability_window(
            session, caller.org_id, user_id, payload.start_date, payload.end_date
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except OverlappingWindowError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail=(
                "Availability window overlaps an existing window "
                f"({exc.conflicting.start_date} to {exc.conflicting.end_date})"
            ),
        ) from exc
    return _to_window_out(window)


@router.get("/{user_id}/availability", response_model=list[AvailabilityWindowOut])
def list_availability_windows_route(
    user_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> list[AvailabilityWindowOut]:
    _require_self_crew(caller, user_id)
    try:
        windows = list_crew_availability_windows(session, caller.org_id, user_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return [_to_window_out(window) for window in windows]


@router.delete("/{user_id}/availability/{window_id}", status_code=status.HTTP_204_NO_CONTENT)
def remove_availability_window_route(
    user_id: int,
    window_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> None:
    _require_self_crew(caller, user_id)
    try:
        remove_availability_window(session, caller.org_id, user_id, window_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except WindowNotFoundError as exc:
        raise HTTPException(
